246			"id valid then null":     `{"id":"INC-1","id":null,"severity":"high","assets":["a"],"owner":"x"}`,
247			"id invalid then valid":  `{"id":7,"id":"INC-1","severity":"high","assets":["a"],"owner":"x"}`,
248			"id valid then invalid":  `{"id":"INC-1","id":7,"severity":"high","assets":["a"],"owner":"x"}`,
249			"id escaped duplicate":   `{"id":"INC-1","` + escapeName("id") + `":"INC-2","severity":"high","assets":["a"],"owner":"x"}`,
250			"id case variant plus":   `{"ID":"INC-9","id":"INC-1","severity":"high","assets":["a"],"owner":"x"}`,
251			"severity duplicate":     `{"id":"INC-1","severity":"low","severity":"high","assets":["a"],"owner":"x"}`,
252			"severity null then set": `{"id":"INC-1","severity":null,"severity":"high","assets":["a"],"owner":"x"}`,
253			"assets duplicate":       `{"id":"INC-1","severity":"high","assets":["a"],"assets":["b"],"owner":"x"}`,
