	// Invalid bodies are rejected even while the store is down.
	invalid := []string{
		`{"ID":"INC-2","severity":"high","assets":["a"],"owner":"x"}`,
		`{"id":"INC-2","id":"INC-2","severity":"high","assets":["a"],"owner":"x"}`,
