		}
		if code := errorCode(t, decoded); code != "invalid_request" {
			t.Fatalf("%s: code = %q, want invalid_request", body, code)
		}
	}

	// A valid body still surfaces the storage failure.
	valid := `{"id":"INC-2","severity":"high","assets":["a"],"owner":"x"}`
