// Package store owns the SQLite file and every write the service performs.
package store

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"slices"
	"strings"
	"time"

	_ "modernc.org/sqlite"
)

// InitialStage is the stage every incident starts in when it is registered.
const InitialStage = "受理"

// stageOrder lists the stages in the only order an incident may follow.
var stageOrder = []string{"受理", "遏制", "清除", "恢复", "关闭"}

// nextStage returns the stage a transition may move to from current, or ""
// when current is the final stage.
func nextStage(current string) string {
	for i, stage := range stageOrder {
		if stage == current && i+1 < len(stageOrder) {
			return stageOrder[i+1]
		}
	}
	return ""
}

// TimelineEntry records one stage of an incident's life together with the
// owner responsible at that point and the UTC time the entry was created.
type TimelineEntry struct {
	Stage string `json:"stage"`
	Owner string `json:"owner"`
	At    string `json:"at"`
}

// Incident is a registered ticket together with its full transition history.
type Incident struct {
	ID       string          `json:"id"`
	Severity string          `json:"severity"`
	Assets   []string        `json:"assets"`
	Stage    string          `json:"stage"`
	Owner    string          `json:"owner"`
	Timeline []TimelineEntry `json:"timeline"`
}

// ErrIncidentConflict is returned when an id is registered again with
// different severity, assets, or owner.
var ErrIncidentConflict = errors.New("incident id already registered with different attributes")

// ErrIncidentNotFound is returned when no incident exists for an id.
var ErrIncidentNotFound = errors.New("incident not found")

// ErrInvalidTransition is returned when a transition does not advance the
// incident exactly one stage along stageOrder.
var ErrInvalidTransition = errors.New("transition must advance exactly one stage")

// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	db *sql.DB
}

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	// A single connection serializes every read and write, so concurrent
	// transitions settle through the conditional UPDATE instead of racing
	// two writers into SQLITE_BUSY.
	db.SetMaxOpenConns(1)
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	return &Store{db: db}, nil
}

// Ping reports whether the storage layer is usable.
func (s *Store) Ping() error { return s.db.Ping() }

// Close releases the database handle.
func (s *Store) Close() error { return s.db.Close() }

// Register stores a new incident and its initial timeline entry in one
// transaction. Re-registering the same id with identical severity, assets
// (order included), and owner returns the stored record unchanged; any
// difference yields ErrIncidentConflict.
func (s *Store) Register(id, severity, owner string, assets []string) (Incident, error) {
	existing, err := s.find(id)
	if err != nil {
		return Incident{}, err
	}
	if existing != nil {
		return resolveDuplicate(existing, severity, owner, assets)
	}

	encoded, err := json.Marshal(assets)
	if err != nil {
		return Incident{}, fmt.Errorf("encode assets: %w", err)
	}
	at := time.Now().UTC().Format(time.RFC3339)

	tx, err := s.db.Begin()
	if err != nil {
		return Incident{}, fmt.Errorf("begin register: %w", err)
	}
	defer tx.Rollback()
	if _, err = tx.Exec(
		"INSERT INTO incidents (id, severity, assets, stage, owner) VALUES (?, ?, ?, ?, ?)",
		id, severity, string(encoded), InitialStage, owner,
	); err == nil {
		if _, err = tx.Exec(
			"INSERT INTO incident_timeline (incident_id, seq, stage, owner, at) VALUES (?, 0, ?, ?, ?)",
			id, InitialStage, owner, at,
		); err == nil {
			err = tx.Commit()
		}
	}
	if err != nil {
		// A concurrent register of the same id may have won the race.
		if existing, findErr := s.find(id); findErr == nil && existing != nil {
			return resolveDuplicate(existing, severity, owner, assets)
		}
		return Incident{}, fmt.Errorf("register incident: %w", err)
	}

	return Incident{
		ID:       id,
		Severity: severity,
		Assets:   assets,
		Stage:    InitialStage,
		Owner:    owner,
		Timeline: []TimelineEntry{{Stage: InitialStage, Owner: owner, At: at}},
	}, nil
}

// Get returns the incident registered under id, or ErrIncidentNotFound.
func (s *Store) Get(id string) (Incident, error) {
	incident, err := s.find(id)
	if err != nil {
		return Incident{}, err
	}
	if incident == nil {
		return Incident{}, ErrIncidentNotFound
	}
	return *incident, nil
}

// List returns every incident matching the optional severity and stage
// filters, ordered by id in UTF-8 byte order. Empty filters match everything.
func (s *Store) List(severity, stage string) ([]Incident, error) {
	query := "SELECT id, severity, assets, stage, owner FROM incidents"
	var clauses []string
	var args []any
	if severity != "" {
		clauses = append(clauses, "severity = ?")
		args = append(args, severity)
	}
	if stage != "" {
		clauses = append(clauses, "stage = ?")
		args = append(args, stage)
	}
	if len(clauses) > 0 {
		query += " WHERE " + strings.Join(clauses, " AND ")
	}
	query += " ORDER BY id"

	rows, err := s.db.Query(query, args...)
	if err != nil {
		return nil, fmt.Errorf("list incidents: %w", err)
	}
	incidents := []Incident{}
	for rows.Next() {
		incident, err := scanIncident(rows)
		if err != nil {
			rows.Close()
			return nil, err
		}
		incidents = append(incidents, incident)
	}
	if err := rows.Err(); err != nil {
		rows.Close()
		return nil, fmt.Errorf("list incidents: %w", err)
	}
	rows.Close()

	for i := range incidents {
		timeline, err := s.timeline(incidents[i].ID)
		if err != nil {
			return nil, err
		}
		incidents[i].Timeline = timeline
	}
	return incidents, nil
}

// find loads one incident by id, returning nil when it does not exist.
func (s *Store) find(id string) (*Incident, error) {
	row := s.db.QueryRow(
		"SELECT id, severity, assets, stage, owner FROM incidents WHERE id = ?", id)
	incident, err := scanIncident(row)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	timeline, err := s.timeline(id)
	if err != nil {
		return nil, err
	}
	incident.Timeline = timeline
	return &incident, nil
}

// timeline loads the transition history of one incident in entry order.
func (s *Store) timeline(id string) ([]TimelineEntry, error) {
	rows, err := s.db.Query(
		"SELECT stage, owner, at FROM incident_timeline WHERE incident_id = ? ORDER BY seq", id)
	if err != nil {
		return nil, fmt.Errorf("read timeline: %w", err)
	}
	defer rows.Close()

	entries := []TimelineEntry{}
	for rows.Next() {
		var entry TimelineEntry
		if err := rows.Scan(&entry.Stage, &entry.Owner, &entry.At); err != nil {
			return nil, fmt.Errorf("read timeline: %w", err)
		}
		entries = append(entries, entry)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("read timeline: %w", err)
	}
	return entries, nil
}

// resolveDuplicate decides whether a repeated registration is the same
// incident (returned unchanged) or a conflicting one.
func resolveDuplicate(existing *Incident, severity, owner string, assets []string) (Incident, error) {
	if existing.Severity == severity && existing.Owner == owner && slices.Equal(existing.Assets, assets) {
		return *existing, nil
	}
	return Incident{}, ErrIncidentConflict
}

// scanner is the common shape of QueryRow/Query results over the incidents table.
type scanner interface {
	Scan(dest ...any) error
}

func scanIncident(row scanner) (Incident, error) {
	var incident Incident
	var encoded string
	if err := row.Scan(&incident.ID, &incident.Severity, &encoded, &incident.Stage, &incident.Owner); err != nil {
		return Incident{}, err
	}
	if err := json.Unmarshal([]byte(encoded), &incident.Assets); err != nil {
		return Incident{}, fmt.Errorf("decode assets: %w", err)
	}
	return incident, nil
}

const schema = `
CREATE TABLE IF NOT EXISTS service_metadata (
	key   TEXT PRIMARY KEY,
	value TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS incidents (
	id       TEXT PRIMARY KEY,
	severity TEXT NOT NULL,
	assets   TEXT NOT NULL,
	stage    TEXT NOT NULL,
	owner    TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS incident_timeline (
	incident_id TEXT NOT NULL REFERENCES incidents(id),
	seq         INTEGER NOT NULL,
	stage       TEXT NOT NULL,
	owner       TEXT NOT NULL,
	at          TEXT NOT NULL,
	PRIMARY KEY (incident_id, seq)
);
`

package api

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"net/url"
	"strings"

	"github.com/gin-gonic/gin"

	"github.com/xjeey8iust/sen-incident-response-flow/internal/store"
)

var validSeverities = map[string]bool{
	"low":      true,
	"medium":   true,
	"high":     true,
	"critical": true,
}

var validStages = map[string]bool{
	"受理": true,
	"遏制": true,
	"清除": true,
	"恢复": true,
	"关闭": true,
}

// NewRouter wires the public HTTP surface. The service contract in README.md
// describes the error shape every entry must keep.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			writeError(c, http.StatusServiceUnavailable, "storage_unavailable", "database is not available")
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	router.POST("/incidents", createIncident(st))
	router.GET("/incidents", queryIncidents(st))

	router.NoRoute(func(c *gin.Context) {
		writeError(c, http.StatusNotFound, "route_not_found", "no route matches this path")
	})
	return router
}

// registerRequest mirrors the accepted registration body. Pointer fields let
// the handler reject missing keys and explicit nulls alike.
type registerRequest struct {
	ID       *string   `json:"id"`
	Severity *string   `json:"severity"`
	Assets   *[]string `json:"assets"`
	Owner    *string   `json:"owner"`
}

// registerFields is the case-sensitive whitelist of accepted registration
// fields. Names are compared after JSON unescaping, so "id" is accepted
// while "ID" is an unknown field.
var registerFields = map[string]bool{
	"id":       true,
	"severity": true,
	"assets":   true,
	"owner":    true,
}

func createIncident(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		payload, ok := decodeRegisterRequest(c.Request.Body)
		if !ok || !payload.valid() {
			writeInvalidRequest(c)
			return
		}

		incident, err := st.Register(*payload.ID, *payload.Severity, *payload.Owner, *payload.Assets)
		if errors.Is(err, store.ErrIncidentConflict) {
			writeError(c, http.StatusConflict, "incident_conflict", "incident id is already registered with different attributes")
			return
		}
		if err != nil {
			writeError(c, http.StatusServiceUnavailable, "storage_unavailable", "database is not available")
			return
		}
		c.JSON(http.StatusCreated, incident)
	}
}

// decodeRegisterRequest parses the registration body token by token so the
// field whitelist stays case-sensitive and duplicate keys are rejected.
// encoding/json's struct decoding cannot do either: it matches tags
// case-insensitively and silently lets a later key overwrite an earlier one.
// Keys arrive already unescaped, so "id" collides with "id" while
// case variants like "ID" fall outside the whitelist.
func decodeRegisterRequest(body io.Reader) (registerRequest, bool) {
	var payload registerRequest
	decoder := json.NewDecoder(body)
	token, err := decoder.Token()
	if err != nil {
		return payload, false
	}
	if delim, ok := token.(json.Delim); !ok || delim != '{' {
		return payload, false
	}
	seen := map[string]bool{}
	for decoder.More() {
		token, err := decoder.Token()
		if err != nil {
			return payload, false
		}
		key, ok := token.(string)
		if !ok || !registerFields[key] || seen[key] {
			return payload, false
		}
		seen[key] = true
		var decodeErr error
		switch key {
		case "id":
			decodeErr = decoder.Decode(&payload.ID)
		case "severity":
			decodeErr = decoder.Decode(&payload.Severity)
		case "assets":
			decodeErr = decoder.Decode(&payload.Assets)
		case "owner":
			decodeErr = decoder.Decode(&payload.Owner)
		}
		if decodeErr != nil {
			return payload, false
		}
	}
	if _, err := decoder.Token(); err != nil {
		return payload, false
	}
	if err := decoder.Decode(&struct{}{}); err != io.EOF {
		return payload, false
	}
	return payload, true
}

// valid reports whether every required field is present and well formed.
func (r *registerRequest) valid() bool {
	if r.ID == nil || strings.TrimSpace(*r.ID) == "" {
		return false
	}
	if r.Severity == nil || !validSeverities[*r.Severity] {
		return false
	}
	if r.Owner == nil || strings.TrimSpace(*r.Owner) == "" {
		return false
	}
	if r.Assets == nil || len(*r.Assets) == 0 {
		return false
	}
	for _, asset := range *r.Assets {
		if strings.TrimSpace(asset) == "" {
			return false
		}
	}
	return true
}

func queryIncidents(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		// Parse the raw query ourselves: URL.Query() silently drops segments
		// with broken percent-escapes or unescaped semicolons, which would
		// turn a malformed filter into an unconditional listing. Any parse
		// error rejects the whole request before the store is touched.
		query, err := url.ParseQuery(c.Request.URL.RawQuery)
		if err != nil {
			writeInvalidQuery(c)
			return
		}
		for key, values := range query {
			if key != "severity" && key != "stage" && key != "id" {
				writeInvalidQuery(c)
				return
			}
			if len(values) != 1 || values[0] == "" {
				writeInvalidQuery(c)
				return
			}
		}

		if id := query.Get("id"); id != "" {
			if len(query) != 1 {
				writeInvalidQuery(c)
				return
			}
			incident, err := st.Get(id)
			if errors.Is(err, store.ErrIncidentNotFound) {
				writeError(c, http.StatusNotFound, "incident_not_found", "no incident is registered with this id")
				return
			}
			if err != nil {
				writeError(c, http.StatusServiceUnavailable, "storage_unavailable", "database is not available")
				return
			}
			c.JSON(http.StatusOK, incident)
			return
		}

		severity := query.Get("severity")
		if severity != "" && !validSeverities[severity] {
			writeInvalidQuery(c)
			return
		}
		stage := query.Get("stage")
		if stage != "" && !validStages[stage] {
			writeInvalidQuery(c)
			return
		}

		incidents, err := st.List(severity, stage)
		if err != nil {
			writeError(c, http.StatusServiceUnavailable, "storage_unavailable", "database is not available")
			return
		}
		c.JSON(http.StatusOK, incidents)
	}
}

func writeInvalidRequest(c *gin.Context) {
	writeError(c, http.StatusBadRequest, "invalid_request", "request body must be a single JSON object with valid id, severity, assets, and owner")
}

func writeInvalidQuery(c *gin.Context) {
	writeError(c, http.StatusBadRequest, "invalid_query", "query parameters are missing, repeated, unknown, or hold invalid values")
}

// writeError keeps the published error shape: a single top-level error object
// whose message never exposes SQL, stack traces, or file paths.
func writeError(c *gin.Context, status int, code, message string) {
	c.JSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
}

