		if _, err := st.Transition("INC-1", stage, "carol"); !errors.Is(err, ErrInvalidTransition) {
			t.Fatalf("transition from 关闭 to %s: err = %v, want ErrInvalidTransition", stage, err)
		}
	}
	got, err := st.Get("INC-1")
